from jinja2.exceptions import UndefinedError

from ansible.errors import AnsibleFilterError, AnsibleUndefinedVariable
from ansible.plugins.filter.core import to_nice_yaml, to_yaml
from ansible.template import AnsibleUndefined, Templar
import yaml

for filter_func in (to_yaml, to_nice_yaml):
    try:
        filter_func(AnsibleUndefined(name='MYSVC_ENV'))
    except UndefinedError as exc:
        assert 'MYSVC_ENV' in str(exc)
    else:
        raise AssertionError('%s serialized an undefined value' % filter_func.__name__)

    try:
        filter_func(object())
    except AnsibleFilterError as exc:
        assert filter_func.__name__ in str(exc)
        assert isinstance(exc.orig_exc, yaml.representer.RepresenterError)
        assert 'cannot represent an object' in str(exc)
    else:
        raise AssertionError('%s did not wrap a YAML error' % filter_func.__name__)

assert yaml.safe_load(to_yaml({'value': 1})) == {'value': 1}
assert yaml.safe_load(to_nice_yaml({'value': 1})) == {'value': 1}
try:
    Templar(loader=None, variables={}).template('{{ missing | to_nice_yaml }}')
except AnsibleUndefinedVariable as exc:
    assert 'missing' in str(exc)
    assert isinstance(exc.__context__, UndefinedError)
else:
    raise AssertionError('templating did not report an undefined variable')
PY"
